  void BuildHardware(TableLayoutPanel layout,Panel oldHeader,FlowLayoutPanel transport,TableLayoutPanel racks){
   hardware=new HardwareSurface{Dock=DockStyle.Fill,Margin=new Padding(0)};layout.Controls.Remove(oldHeader);layout.Controls.Remove(transport);layout.Controls.Remove(racks);layout.Controls.Add(hardware,0,0);layout.SetRowSpan(hardware,3);
