   Button undo=Btn("UNDO / REDO",115,delegate{Engine.Undo(Engine.Config.SelectedTrack,false);});undo.MouseDown+=delegate(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Right)Engine.Undo(Engine.Config.SelectedTrack,true);};hardware.Controls.Add(undo);
