   lcd=new HardwareLcd{Engine=Engine};hardware.Controls.Add(lcd);lcd.Controls.Add(memory);memory.SetBounds(10,8,55,25);memory.BackColor=Color.FromArgb(31,42,131);memory.ForeColor=Color.White;memory.Font=new Font("Consolas",13,FontStyle.Bold);lcd.Controls.Add(sessionName);sessionName.SetBounds(10,37,190,22);sessionName.BorderStyle=BorderStyle.None;sessionName.BackColor=Color.FromArgb(29,36,119);sessionName.ForeColor=Color.White;
   centerSection=Theme.Combo(new string[]{"INPUT FX","TRACK FX"});centerSlot=Theme.Combo(new string[]{"FX A","FX B","FX C","FX D"});centerType=Theme.Combo(FxCatalog.Input);hardware.Controls.Add(centerSection);hardware.Controls.Add(centerSlot);hardware.Controls.Add(centerType);
