  FxConfig HardwareEffect{get{ChainConfig c=hardwareInput?Engine.Config.InputFx:Engine.Config.TrackFx;return c.Slots[c.Bank*4+hardwareSlot];}}
  void SelectHardwareFx(bool input,int slot){if(centerType==null)return;hardwareInput=input;hardwareSlot=Math.Max(0,Math.Min(3,slot));FxBar bar=input?inputBar:trackBar;if(bar.SelectedSlot!=hardwareSlot)bar.SelectSlot(hardwareSlot);hardwareUpdating=true;centerSection.SelectedIndex=input?0:1;centerSlot.SelectedIndex=hardwareSlot;centerType.Items.Clear();centerType.Items.AddRange(input?FxCatalog.Input:FxCatalog.All);centerType.SelectedItem=HardwareEffect.Type;hardwareUpdating=false;RefreshHardware();}
  void SetHardwareMacro(int at,float v){lock(Engine.Gate){FxConfig f=HardwareEffect;if(f.Detail==null)f.Detail=new FxDetail();if(at==3)f.Mix=v;else if(at==2){if(f.Detailed)f.Detail.RateHz=.01f*(float)Math.Pow(2000,v);else f.Rate=v;}else if(at==1){if(f.Detailed&&f.Type=="LO-FI")f.Detail.SampleDivisor=1+(int)Math.Round(v*31);else if(f.Detailed&&(f.Type=="LPF"||f.Type=="BPF"||f.Type=="HPF"))f.Detail.Depth=v;else f.Feedback=v*.94f;}else{if(f.Detailed&&f.Type=="LO-FI")f.Detail.Bits=1+(int)Math.Round(v*23);else if(f.Detailed&&(f.Type=="LPF"||f.Type=="BPF"||f.Type=="HPF"||f.Type=="RING.MOD"))f.Detail.Cutoff=20*(float)Math.Pow(900,v);else if(f.Detailed&&f.Type.Contains("DELAY"))f.Detail.TimeMs=1+v*1999;else if(f.Detailed&&f.Type.Contains("REVERB"))f.Detail.ReverbSeconds=.1f+v*9.9f;else f.Amount=v;}Engine.Dirty=true;}RefreshHardware();}
  void RefreshHardware(){if(hardware==null)return;if(!inputDial.Dragging)inputDial.Value=Engine.Config.InputGain/4;inputDial.Readout=(int)(Engine.Config.InputGain*100)+"%";if(!outputDial.Dragging)outputDial.Value=Engine.Config.Master/2;outputDial.Readout=(int)(Engine.Config.Master*100)+"%";if(!tempoDial.Dragging)tempoDial.Value=(Engine.Config.Bpm-20)/280;tempoDial.Readout=Engine.Config.Bpm.ToString("0.#");FxConfig f=HardwareEffect;if(!hardwareUpdating&&Convert.ToString(centerType.SelectedItem)!=f.Type){hardwareUpdating=true;centerType.SelectedItem=f.Type;hardwareUpdating=false;}FxDetail d=f.Detail??new FxDetail();string[] names={"AMOUNT","FEEDBACK","RATE","MIX"};float[] values={f.Amount,f.Feedback/.94f,f.Detailed?(float)(Math.Log(Math.Max(.01,d.RateHz)/.01)/Math.Log(2000)):f.Rate,f.Mix};string[] read={Math.Round(f.Amount*100)+"%",Math.Round(f.Feedback*100)+"%",f.Detailed?d.RateHz.ToString("0.00")+" Hz":Math.Round(f.Rate*100)+"%",Math.Round(f.Mix*100)+"%"};if(f.Detailed){if(f.Type=="LO-FI"){names[0]="BITS";values[0]=(d.Bits-1)/23f;read[0]=d.Bits.ToString();names[1]="SAMPLE /";values[1]=(d.SampleDivisor-1)/31f;read[1]="1/"+d.SampleDivisor;}else if(f.Type=="LPF"||f.Type=="BPF"||f.Type=="HPF"||f.Type=="RING.MOD"){names[0]=f.Type=="RING.MOD"?"FREQ":"CUTOFF";values[0]=(float)(Math.Log(d.Cutoff/20)/Math.Log(900));read[0]=d.Cutoff.ToString("0")+" Hz";names[1]="DEPTH";values[1]=d.Depth;read[1]=Math.Round(d.Depth*100)+"%";}else if(f.Type.Contains("DELAY")){names[0]="TIME";values[0]=(d.TimeMs-1)/1999;read[0]=d.TimeMs.ToString("0")+" ms";}else if(f.Type.Contains("REVERB")){names[0]="TIME";values[0]=(d.ReverbSeconds-.1f)/9.9f;read[0]=d.ReverbSeconds.ToString("0.0")+" s";}}for(int i=0;i<4;i++){macroDials[i].Caption=names[i];macroDials[i].Readout=read[i];if(!macroDials[i].Dragging)macroDials[i].Value=values[i];macroDials[i].Invalidate();}lcd.Effect=(hardwareInput?"INPUT":"TRACK")+" · "+(char)('A'+hardwareSlot);lcd.Parameter=f.Type;lcd.Invalidate();}
 }
